 void until(BooleanSupplier test,Work next){until(test,next,600);}
 void until(BooleanSupplier test,Work next,int remaining){later(1,()->{if(!trade.processing()&&!supplies.busy()&&test.getAsBoolean()){next.run();return;}if(remaining==0)throw new AssertionError("Timed out caravans="+repo.allCaravans().stream().map(c->c.id()+":"+c.settlement()).toList()+" supplies="+supplies.all());callTick(trade);callTick(supplies);until(test,next,remaining-1);});}
