 @Override public void onEnable(){if(!Files.isRegularFile(Path.of("ALLOW_DISPOSABLE_RAID_PROBE"))||!"127.0.0.1".equals(getServer().getIp())){Bukkit.getPluginManager().disablePlugin(this);return;}proof=getDataFolder().toPath();try{Files.createDirectories(proof);phase=Files.exists(proof.resolve("first-passed.txt"))?"restart":"first";}catch(Exception e){fail(e);return;}SuiteState.freeze("NeverLandTownyTrade");Bukkit.getGlobalRegionScheduler().runDelayed(this,t->{world=Bukkit.getWorlds().getFirst();origin=new Location(world,8,140,8);world.getChunkAtAsync(0,0).whenComplete((c,e)->{if(e!=null)fail(e);else later(1,this::setup);});},40);}
 @SuppressWarnings("unchecked")Player player(){var scheduler=(io.papermc.paper.threadedregions.scheduler.EntityScheduler)Proxy.newProxyInstance(Player.class.getClassLoader(),new Class<?>[]{io.papermc.paper.threadedregions.scheduler.EntityScheduler.class},(p,m,a)->switch(m.getName()){case "runDelayed"->Bukkit.getRegionScheduler().runDelayed((Plugin)a[0],origin,(Consumer<io.papermc.paper.threadedregions.scheduler.ScheduledTask>)a[1],((Number)a[3]).longValue());default->throw new UnsupportedOperationException(m.getName());});return(Player)Proxy.newProxyInstance(Player.class.getClassLoader(),new Class<?>[]{Player.class},(p,m,a)->switch(m.getName()){case "getUniqueId"->M;case "getName"->"TradeBudgetMayor";case "getWorld"->world;case "getLocation"->origin;case "isOnline"->true;case "isOp"->false;case "hasPermission"->permitted;case "getScheduler"->scheduler;case "hashCode"->M.hashCode();case "equals"->p==a[0];default->null;});}
 void setup()throws Exception{
  owner=(MintTownyTrade)Bukkit.getPluginManager().getPlugin("NeverLandTownyTrade");trade=(TradeService)field(owner,"trade");repo=(TradeRepository)field(owner,"repository");supplies=owner.supplies();journal=(SupplyJournal)field(supplies,"repo");((org.bukkit.scheduler.BukkitTask)field(trade,"task")).cancel();((org.bukkit.scheduler.BukkitTask)field(supplies,"task")).cancel();set(trade,"legacyReviews",true);treasury=(TreasuryService)Bukkit.getServicesManager().load(TownyTreasuryApi.class);data=(DataStore)field(Bukkit.getPluginManager().getPlugin("NeverLandTownyBuilds"),"dataStore");storage=Bukkit.getServicesManager().load(BuildingStorageApi.class);mayor=player();set(trade,"fundingPlayers",(Function<UUID,Player>)(uuid->uuid.equals(M)?mayor:null));check(owner.isEnabled()&&supplies.available()&&treasury!=null&&storage!=null,"actual Trade0.3.1 Treasury and Builds APIs enabled");
  if(phase.equals("first")){var u=TownyUniverse.getInstance();for(UUID uuid:List.of(SELLER,BUYER)){String name=uuid.equals(BUYER)?"TradeBudgetBuyer":"TradeBudgetSeller";u.newTownInternal(name,uuid);var t=town(uuid);var r=u.getDataSource().newResident(uuid.equals(BUYER)?"TradeBudgetMayor":"TradeSellerMayor",uuid.equals(BUYER)?M:id("sellerMayor"));r.setTown(t);t.setMayor(r);r.save();t.save();var items=data.town(uuid).storage();if(uuid.equals(SELLER))for(int i=0;i<16;i++)items[i]=new ItemStack(Material.STONE,64);data.town(uuid).setStorage(items,items.length);}data.markDirty();data.saveOrThrow();money.put(BUYER,10000D);money.put(SELLER,0D);}else{var p=new Properties();try(var in=Files.newInputStream(proof.resolve("bank.properties"))){p.load(in);}p.forEach((k,v)->money.put(UUID.fromString(k.toString()),Double.parseDouble(v.toString())));}
  bank();sync(200);
 }
 void sync(int remaining)throws Exception{try{treasury.sync(town(BUYER));treasury.sync(town(SELLER));}catch(IllegalStateException busy){if(remaining==0)throw busy;later(1,()->sync(remaining-1));return;}SuiteState.thaw(owner.getName());if(phase.equals("first"))seed(C,100,this::unavailable);else resumed();}
 void seed(UUID id,double price,Work next)throws Exception{long now=System.currentTimeMillis();var route=List.of(new RoutePoint(world.getUID(),world.getName(),0,140,0,RoutePoint.Kind.TOWN,"seller",1,SELLER),new RoutePoint(world.getUID(),world.getName(),30,140,0,RoutePoint.Kind.TOWN,"buyer",1,BUYER));var c=new Caravan(id,SELLER,BUYER,"stone",new ItemStack(Material.STONE),64,64,price,price,Map.of(),route,now,now+60000,now+30000,false,true,CaravanStatus.ACTIVE);c.fundingActor(M);c.funding(new TreasuryFunding().freeze(c.operation("debit"),BUYER,M,Math.round(price*100),"infrastructure","trade","Native caravan "+id));var offer=new TradeOffer(id,SELLER,BUYER,"stone",now,now+3600000);await(repo.putOffer(offer).thenCompose(v->repo.accept(offer,c)),next);}
 void unavailable()throws Exception{var services=Bukkit.getServicesManager();services.unregister(TownyTreasuryApi.class,treasury);ticks(15,()->{check(debits==0&&cents(BUYER)==1000000&&caravan(C).settlement().equals("PREPARED"),"missing installed Treasury holds exact accepted caravan without direct debit fallback");services.register(TownyTreasuryApi.class,treasury,Bukkit.getPluginManager().getPlugin("NeverLandTownyTreasuryPlus"),ServicePriority.Normal);until(()->caravan(C).settlement().equals("ACTIVE"),this::cancelPaid);});}
 void cancelPaid()throws Exception{var c=caravan(C);check(debits==1&&cents(BUYER)==990000&&stock(SELLER)==960,"real warehouse reservation and exact Treasury debit precede active caravan");check(treasury.debitStatus(c.operation("debit")).get("actor").equals(M.toString()),"actor revalidated through regional player callback matches bank receipt");check(trade.cancelCaravan(c)==TradeService.CancelResult.PROCESSING,"paid administrative cancellation acknowledges asynchronous refund");until(()->settled(C),()->{check(debits==1&&credits==1&&cents(BUYER)==1000000&&stock(SELLER)==1024,"exact original Treasury refund and reserved cargo return once");check(treasury.debitStatus(c.operation("refund:"+BUYER)).get("kind").equals("REFUND"),"cancellation uses backed Treasury refund receipt");permitted=false;seed(DENIED,100,()->until(()->settled(DENIED),this::denied));});}
 void denied()throws Exception{check(debits==1&&cents(BUYER)==1000000&&stock(SELLER)==1024,"revoked player permission before bank request cancels without charging or losing cargo");permitted=true;seed(POOR,20000,()->until(()->settled(POOR),()->{check(debits==1&&cents(BUYER)==1000000&&stock(SELLER)==1024,"insufficient treasury funds reject purchase and return all cargo");seedSupply(S,4000,()->until(()->supply(S).deliveries()==1,this::supplied));}));}
 void seedSupply(UUID id,long amount,Work next)throws Exception{long now=System.currentTimeMillis();UUID attempt=id(id+"-attempt");var terms=new SupplyContract.Terms(id,SELLER,BUYER,Base64.getEncoder().encodeToString(new ItemStack(Material.STONE).serializeAsBytes()),"Stone",8,amount,1,now,now+3600000);var c=new SupplyContract(terms,SupplyContract.Status.ACTIVE,Set.of(),now,now,0,List.of(),"Explicit accepted reservation fixture",new SupplyContract.Attempt(attempt,SupplyContract.Phase.DEBIT_READY,now));check(storage.reserveTrade(SELLER,BUYER,attempt,new ItemStack(Material.STONE),8).equals("RESERVED"),"real Builds warehouse reserves supply before accepted debit intent");var funding=new TreasuryFunding().freeze(SupplyJournal.debit(attempt),BUYER,new UUID(0,0),amount,"infrastructure","trade","Поставка "+attempt+" / "+id);await(journal.put(c,M,new SupplyJournal.Payment(attempt,"TREASURY",funding),false,List.of(),null),next);}
 void supplied()throws Exception{check(debits==2&&credits==2&&cents(BUYER)==996000&&cents(SELLER)==4000&&stock(BUYER)==8&&stock(SELLER)==1016,"recurring supply transfers exact money and real warehouse cargo once");check(journal.image().actors().get(S).equals(M)&&!journal.image().payments().containsKey(S),"accepting mayor is preserved after completed supply clears only its pending payment");loseCredit=true;seedSupply(UNKNOWN,3000,()->until(()->supply(UNKNOWN).attempt()!=null&&supply(UNKNOWN).attempt().phase()==SupplyContract.Phase.CREDIT_PENDING&&credits==3,this::unknown));}
 void unknown()throws Exception{int before=credits;var c=supply(UNKNOWN);ticks(20,()->{check(credits==before&&cents(SELLER)==7000&&supply(UNKNOWN).attempt().phase()==SupplyContract.Phase.CREDIT_PENDING,"lost seller-bank response retains unknown credit and never pays automatically again");await(supplies.resolve(UNKNOWN.toString(),c.attempt().id(),"credit-paid"),()->until(()->supply(UNKNOWN).deliveries()==1,()->{check(credits==3&&stock(BUYER)==16&&stock(SELLER)==1008,"manual verified seller receipt closes supply without duplicated money or cargo");seedSupply(RESTART,2000,()->{SuiteState.freeze(owner.getName());check(supply(RESTART).attempt().phase()==SupplyContract.Phase.DEBIT_READY&&debits==3,"accepted unpaid supply and reserved cargo survive deliberate owner pause");finish();});}));});}
 void resumed()throws Exception{check(debits==0&&credits==0&&cents(BUYER)==993000&&cents(SELLER)==7000&&stock(BUYER)==16&&stock(SELLER)==1000,"full restart restores confirmed money resources and unpaid reserved shipment");check(supply(RESTART).attempt().phase()==SupplyContract.Phase.DEBIT_READY&&journal.image().payments().get(RESTART).terms().operation().equals(SupplyJournal.debit(supply(RESTART).attempt().id())),"restart preserves exact pending supply operation rather than generating a new debit");until(()->supply(RESTART).deliveries()==1,()->{check(debits==1&&credits==1&&cents(BUYER)==991000&&cents(SELLER)==9000&&stock(BUYER)==24&&stock(SELLER)==1000,"saved supply settles exactly once after JVM restart");ticks(30,()->{check(debits==1&&credits==1&&repo.allCaravans().isEmpty()&&supplies.all().stream().allMatch(c->c.attempt()==null),"completed caravan and supply receipts do not replay on later ticks");finish();});});}
 void finish()throws Exception{var p=new Properties();money.forEach((k,v)->p.setProperty(k.toString(),v.toString()));try(var out=Files.newOutputStream(proof.resolve("bank.properties"))){p.store(out,"Explicit deterministic bank backend");}TownySettings.setProperty("economy.using_economy",false);TownyUniverse.getInstance().getDataSource().saveAll();Files.writeString(proof.resolve(phase+"-passed.txt"),"PASS "+checks+" assertions; real Folia/Towny/Builds/Trade/Treasury, exact budget receipts, both warehouse APIs, permissions, insufficient funds, unknown credit and restart; explicit accepted contract/reservation, offline Player/EntityScheduler and deterministic economy adapter; no live Vault or client claimed\n");Bukkit.getGlobalRegionScheduler().run(this,t->Bukkit.shutdown());}
 void bank()throws Exception{var adapter=(EconomyAdapter)Proxy.newProxyInstance(EconomyAdapter.class.getClassLoader(),new Class<?>[]{EconomyAdapter.class},(p,m,a)->{Account account=a!=null&&a.length>0&&a[0] instanceof Account x?x:null;UUID uuid=account==null?null:account.getUUID();double old=uuid==null?0D:money.getOrDefault(uuid,0D);return switch(m.getName()){case "name","toString"->"Native trade budget fixture";case "hasAccount"->true;case "getBalance"->old;case "newAccount","deleteAccount"->null;case "getFormattedBalance"->String.valueOf(a[0]);case "renameAccount"->true;case "setBalance"->{money.put(uuid,(Double)a[1]);yield true;}case "add","subtract"->{if(SuiteState.held())throw new AssertionError("bank invoked while holding SuiteState");boolean add=m.getName().equals("add");double value=(Double)a[1];if(!add&&old<value)yield false;money.put(uuid,old+(add?value:-value));if(add){credits++;if(loseCredit&&uuid.equals(SELLER)){loseCredit=false;throw new IllegalStateException("Explicit lost seller credit response");}}else debits++;yield true;}default->throw new UnsupportedOperationException(m.getName());};});var f=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");f.setAccessible(true);var unsafe=(sun.misc.Unsafe)f.get(null);var provider=(EconomyProvider)unsafe.allocateInstance(Class.forName("com.palmergames.bukkit.towny.object.economy.provider.ReserveEconomyProvider",false,Towny.class.getClassLoader()));for(var entry:Map.of("economy",adapter,"provider",provider).entrySet()){var x=TownyEconomyHandler.class.getDeclaredField(entry.getKey());x.setAccessible(true);x.set(null,entry.getValue());}TownySettings.setProperty("economy.using_economy",true);}
